describe('Video Modal Pause Functionality', () => {
  beforeEach(() => {
    cy.visit('/video-modal');
  });

  it('should pause the video when modal is closed', () => {
    // Open the modal
    cy.get('[data-testid="open-video-modal-btn"]').click();
    cy.get('[data-testid="video-modal"]').should('be.visible');

    // Verify video is playing
    cy.get('[data-testid="video-player"]').should('have.attr', 'src');
    cy.get('[data-testid="video-player"]').should('be.visible');

    // Get the video element
    cy.get('[data-testid="video-player"]').then(($videoPlayer) => {
      const video = $videoPlayer[0];
      const videoElement = video.querySelector('video');
      const playbackRate = videoElement.getAttribute('playbackRate');
      expect(playbackRate).to.equal('1');
    });

    // Close the modal
    cy.get('[data-testid="close-video-modal-btn"]').click();

    // Verify modal is hidden
    cy.get('[data-testid="video-modal"]').should('not.exist');

    // Verify video is paused
    cy.get('[data-testid="video-player"]').then(($videoPlayer) => {
      const videoElement = $videoPlayer[0].querySelector('video');
      const playbackRate = videoElement.getAttribute('playbackRate');
      expect(playbackRate).to.equal('0');
    });
  });

  it('should handle edge case when modal is closed while video is buffering', () => {
    // Open the modal
    cy.get('[data-testid="open-video-modal-btn"]').click();
    cy.get('[data-testid="video-modal"]').should('be.visible');

    // Verify video is buffering
    cy.get('[data-testid="video-player"]').then(($videoPlayer) => {
      const videoElement = $videoPlayer[0].querySelector('video');
      const buffered = videoElement.getAttribute('buffered');
      expect(buffered).to.not.be.empty;
    });

    // Close the modal while buffering
    cy.get('[data-testid="close-video-modal-btn"]').click();

    // Verify modal is hidden
    cy.get('[data-testid="video-modal"]').should('not.exist');

    // Verify video is paused
    cy.get('[data-testid="video-player"]').then(($videoPlayer) => {
      const videoElement = $videoPlayer[0].querySelector('video');
      const playbackRate = videoElement.getAttribute('playbackRate');
      expect(playbackRate).to.equal('0');
    });

    // Verify buffered content is still available
    cy.get('[data-testid="video-player"]').then(($videoPlayer) => {
      const videoElement = $videoPlayer[0].querySelector('video');
      const buffered = videoElement.getAttribute('buffered');
      expect(buffered).to.not.be.empty;
    });
  });
});
